// NPC Constructor Héroe v2.1 (Declarativo OOP Standard + 100% Caminata Continuada)
(async function() {
  if (!game.defineStandardAgent) {
    try {
      var res = await fetch('/api/snippets/base-npc-skills');
      var snip = await res.json();
      if (snip && snip.code) (new Function(snip.code))();
    } catch(e) { console.error('Error cargando base-npc-skills:', e); }
  }

  await game.addMaterial('sand');
  await game.addMaterial('yellow_concrete');

  game.defineStandardAgent({
    id: 'constructor_heroe',
    name: 'Constructor Héroe (Yellow Concrete)',
    block: 'yellow_concrete',
    buildBlock: 'yellow_concrete',
    triggerFloor: 'sand',
    margin: 1,
    passengers: true,
    tickMs: 200,
    skills: {
      construccionEnCapa: true,
      saltoTactico: false
    }
  });
})();
